import type React from "react";
import {Audio, getInputProps, interpolate, staticFile, useVideoConfig} from "remotion";

// Each film has its own original track, generated by scripts/make-music.py into public/music/
// (mastered with ffmpeg compressor + loudnorm to ~-14 LUFS; no voiceover, so full level).
// Default balance: music bed at 0.32 (~-10 dB) so SFX sit clearly on top; a final loudnorm pass
// (scripts/master-reel.sh) brings the full mix to -14 LUFS. 0.5s fade-in, 1s fade-out ending on the last frame.
// duckAt: frames of key SFX; music dips by ~5 dB (x0.56) around each one (3f attack, 10f hold, 14f release).
export const musicLevel = 0.32;
const duckDepth = 0.56;
const duckGain = (f: number, duckAt: readonly number[]) =>
  duckAt.reduce((g, d) => Math.min(g, interpolate(f, [d - 3, d, d + 10, d + 24], [1, duckDepth, duckDepth, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"})), 1);

export const ReelMusic: React.FC<{readonly src: string; readonly volume?: number; readonly duckAt?: readonly number[]}> = ({src, volume = musicLevel, duckAt = []}) => {
  const {fps, durationInFrames} = useVideoConfig();
  if (getInputProps().stem === "sfx") return null;
  return (
    <Audio
      src={staticFile(src)}
      loop
      volume={(f) =>
        interpolate(
          f,
          [0, 0.5 * fps, durationInFrames - 1 - fps, durationInFrames - 1],
          [0, volume, volume, 0],
          {extrapolateLeft: "clamp", extrapolateRight: "clamp"},
        ) * duckGain(f, duckAt)
      }
    />
  );
};
